#!/usr/bin/env node
/**
 * Sync portal .env files from the canonical Docker env (.env.docker).
 * Emits server/canonical keys only — no VITE_* (see vite.config envPrefix).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const args = process.argv.slice(2);
const dryRun = args.includes('--dry-run');
const fromIdx = args.indexOf('--from');
const sourceFile = path.join(
  repoRoot,
  fromIdx !== -1 && args[fromIdx + 1] ? args[fromIdx + 1] : '.env.docker',
);

/** Read value from source, with legacy VITE_* fallback when migrating old .env.docker */
function get(src, key, legacyViteKey) {
  if (src.has(key)) return src.get(key);
  if (legacyViteKey && src.has(legacyViteKey)) return src.get(legacyViteKey);
  return undefined;
}

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`❌ Source not found: ${filePath}`);
    console.error('   Copy .env.docker.example → .env.docker and fill secrets first.');
    process.exit(1);
  }
  const map = new Map();
  for (const line of fs.readFileSync(filePath, 'utf8').split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const eq = t.indexOf('=');
    if (eq <= 0) continue;
    map.set(t.slice(0, eq).trim(), t.slice(eq + 1));
  }
  return map;
}

function renderEnv(title, rows) {
  const lines = [
    `# ${title}`,
    `# Generated by: npm run env:sync`,
    `# Source: ${path.basename(sourceFile)} — re-run after changing shared secrets/keys`,
    `# No VITE_* keys — client vars use canonical names (API_URL, GCP_REGION, etc.)`,
    '',
  ];
  for (const [k, v] of Object.entries(rows)) {
    if (k.startsWith('VITE_')) continue;
    lines.push(`${k}=${v}`);
  }
  lines.push('');
  return lines.join('\n');
}

function writeEnv(relPath, content) {
  const full = path.resolve(repoRoot, relPath);
  if (dryRun) {
    console.log(`[dry-run] Would write ${relPath} (${content.split('\n').length} lines)`);
    return;
  }
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, 'utf8');
  console.log(`✅ ${relPath}`);
}

const src = parseEnvFile(sourceFile);
const dbPass = get(src, 'DB_PASSWORD', null) || get(src, 'POSTGRES_PASSWORD', null) || 'postgres';
const jwt = get(src, 'JWT_SECRET', null) || 'izara-jwt-secret-key-phase1-2026-min-32-chars';
const gemini = get(src, 'GEMINI_API_KEY', 'VITE_GEMINI_API_KEY') || 'xxxxx';
const googleClient = get(src, 'GOOGLE_CLIENT_ID', null) || '';
const googleMaps = get(src, 'GOOGLE_MAPS_API_KEY', 'VITE_GOOGLE_MAPS_API_KEY') || '';
const googleSpeech = get(src, 'GOOGLE_SPEECH_API_KEY', 'VITE_GOOGLE_SPEECH_API_KEY') || '';
const googleCal = get(src, 'GOOGLE_CALENDAR_API_KEY', null) || googleSpeech;
const recordingKey = get(src, 'RECORDING_ENCRYPTION_KEY', null) || '';
const jibriSecret = get(src, 'JIBRI_WEBHOOK_SECRET', null) || '';
const meetingPublic =
  get(src, 'MEETING_PUBLIC_URL', 'VITE_MEETING_SERVER_URL') || 'http://localhost:3020';
const meetingServer = get(src, 'MEETING_SERVER_URL', null) || meetingPublic;

const sharedDb = {
  DB_HOST: 'localhost',
  DB_PORT: '5433',
  DB_NAME: get(src, 'DB_NAME', null) || 'izara_phase1',
  DB_USER: get(src, 'DB_USER', null) || 'postgres',
  DB_PASSWORD: dbPass,
  DATABASE_URL: `postgresql://postgres:${encodeURIComponent(dbPass)}@localhost:5433/izara_phase1`,
  USE_POSTGRESQL: 'true',
};

const patientEnv = renderEnv('Izara Patient Portal — npm dev (backend :3004, Vite :3005)', {
  NODE_ENV: 'development',
  PORT: '3004',
  API_URL: 'http://localhost:3005',
  AUTH_PORTAL_URL: 'http://localhost:3005/auth',
  PATIENT_APP_URL: 'http://localhost:3005/home',
  WEBSOCKET_URL: 'ws://localhost:3005/ws',
  MEETING_SERVER_URL: 'http://localhost:3020',
  MEETING_PUBLIC_URL: 'http://localhost:3020',
  ...sharedDb,
  GCP_PROJECT_ID: get(src, 'GCP_PROJECT_ID', null) || 'izara-telemedicine',
  GCP_REGION: get(src, 'GCP_REGION', 'VITE_GCP_REGION') || 'asia-southeast1',
  GOOGLE_CLIENT_ID: googleClient,
  GOOGLE_MAPS_API_KEY: googleMaps,
  GOOGLE_MAPS_MAP_ID: get(src, 'GOOGLE_MAPS_MAP_ID', null) || '',
  GOOGLE_CALENDAR_API_KEY: googleCal,
  GOOGLE_MEET_API_KEY: googleCal,
  GEMINI_API_KEY: gemini,
  GEMINI_MODEL: get(src, 'GEMINI_MODEL', 'VITE_GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JITSI_DOMAIN: get(src, 'JITSI_DOMAIN', 'VITE_JITSI_DOMAIN') || 'meet.jit.si',
  JITSI_APP_ID: get(src, 'JITSI_APP_ID', null) || 'izara-telemedicine',
  JWT_SECRET: jwt,
});

const doctorEnv = renderEnv('Izara Doctor Portal — npm dev (Vite :3010, auth :3011, API :3009)', {
  NODE_ENV: 'development',
  AUTH_PORT: '3011',
  API_URL: 'http://localhost:3010',
  AUTH_URL: 'http://localhost:3011/auth',
  DOCTOR_APP_URL: 'http://localhost:3010',
  WEBSOCKET_URL: 'ws://localhost:3011/ws',
  MEETING_SERVER_URL: 'http://localhost:3020',
  MEETING_PUBLIC_URL: 'http://localhost:3020',
  UPLOADS_DIR: './uploads',
  CORS_ORIGINS:
    'http://localhost:3010,http://localhost:3005,http://localhost:3011,http://localhost:3020',
  ...sharedDb,
  GCP_PROJECT_ID: get(src, 'GCP_PROJECT_ID', null) || 'izara-telemedicine',
  GCP_REGION: get(src, 'GCP_REGION', 'VITE_GCP_REGION') || 'asia-southeast1',
  GOOGLE_CLIENT_ID: googleClient,
  GOOGLE_MAPS_API_KEY: googleMaps,
  GOOGLE_CALENDAR_API_KEY: googleCal,
  GOOGLE_MEET_API_KEY: googleCal,
  GOOGLE_SPEECH_API_KEY: googleSpeech,
  GEMINI_API_KEY: gemini,
  GEMINI_MODEL: get(src, 'GEMINI_MODEL', 'VITE_GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JITSI_DOMAIN: get(src, 'JITSI_DOMAIN', 'VITE_JITSI_DOMAIN') || 'meet.jit.si',
  JITSI_APP_ID: get(src, 'JITSI_APP_ID', null) || 'izara-telemedicine',
  JWT_SECRET: jwt,
  DEMO_AUTO_LOGIN: get(src, 'DEMO_AUTO_LOGIN', null) || '1',
  DEMO_AUTO_MEETING: get(src, 'DEMO_AUTO_MEETING', null) || '1',
  DEMO_DOCTOR_EMAIL: get(src, 'DEMO_DOCTOR_EMAIL', null) || 'doctor.test@izara.com',
  DEMO_DOCTOR_PASSWORD: get(src, 'DEMO_DOCTOR_PASSWORD', null) || 'IzaraDoctor@2024',
  // Keep concurrent GATE0 / E2E / unit logins from invalidating each other's sessions
  E2E_ALLOW_PARALLEL_SESSIONS:
    get(src, 'E2E_ALLOW_PARALLEL_SESSIONS', null) || '1',
});

const meetingEnv = renderEnv('Izara Meeting Server — npm dev (:3020)', {
  NODE_ENV: 'development',
  PORT: '3020',
  ...sharedDb,
  JITSI_DOMAIN: get(src, 'JITSI_DOMAIN', 'VITE_JITSI_DOMAIN') || 'meet.jit.si',
  JITSI_APP_ID: get(src, 'JITSI_APP_ID', null) || 'izara-telemedicine',
  GOOGLE_SPEECH_API_KEY: googleSpeech,
  GOOGLE_CLOUD_SPEECH_API_KEY: googleSpeech,
  GEMINI_API_KEY: gemini,
  GEMINI_MODEL: get(src, 'GEMINI_MODEL', 'VITE_GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JWT_SECRET: jwt,
  JWT_EXPIRES_IN: get(src, 'JWT_EXPIRES_IN', null) || '24h',
  CORS_ORIGINS:
    'http://localhost:3005,http://localhost:3010,http://localhost:3020,http://127.0.0.1:3005,http://127.0.0.1:3010,http://127.0.0.1:3020',
  RECORDING_ENCRYPTION_KEY: recordingKey,
  JIBRI_WEBHOOK_SECRET: jibriSecret,
  RECORDINGS_DIR: './recordings',
});

const rootEnv = renderEnv('Isara Anywhere root — Vitest / Playwright / gate scripts', {
  GCP_PROJECT_ID: get(src, 'GCP_PROJECT_ID', null) || 'izara-telemedicine',
  GCP_REGION: get(src, 'GCP_REGION', 'VITE_GCP_REGION') || 'asia-southeast1',
  GOOGLE_CLIENT_ID: googleClient,
  GOOGLE_CLIENT_SECRET: get(src, 'GOOGLE_CLIENT_SECRET', null) || '',
  GEMINI_API_KEY: gemini,
  GEMINI_MODEL: get(src, 'GEMINI_MODEL', 'VITE_GEMINI_MODEL') || 'gemini-3.1-flash-lite',
  JWT_SECRET: jwt,
  RECORDING_ENCRYPTION_KEY: recordingKey,
  JIBRI_WEBHOOK_SECRET: jibriSecret,
  ...sharedDb,
  POSTGRES_USER: 'postgres',
  POSTGRES_PASSWORD: dbPass,
  POSTGRES_DB: 'izara_phase1',
  PATIENT_URL: 'http://localhost:3005',
  DOCTOR_URL: 'http://localhost:3010',
  MEETING_URL: 'http://localhost:3020',
  MEETING_SERVER_URL: meetingServer,
  MEETING_PUBLIC_URL: meetingPublic,
  TEST_ENV: 'local',
  // Preserve cloud DB password for cleanup:cloud-test-only / db-tool --target cloud
  CLOUD_DB_PASSWORD: get(src, 'CLOUD_DB_PASSWORD', null) || '',
});

console.log(`\n📋 Sync portal .env from ${path.relative(repoRoot, sourceFile)}\n`);
// Sibling layout (New-Isara-Anywhere): issara-workspace + ../issara-{patient,doctor,jitsi}
writeEnv('../issara-patient/.env', patientEnv);
writeEnv('../issara-doctor/.env', doctorEnv);
writeEnv('../issara-jitsi/.env', meetingEnv);
writeEnv('.env', rootEnv);
console.log(dryRun ? '\n(dry-run — no files written)\n' : '\nDone. Start npm run dev from issara-workspace.\n');
